import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type PieChartsComparisonProps = Record<string, any>;

const DonutChart: React.FC<{
  progress: number;
  color: string;
  size: number;
  strokeWidth: number;
  label: string;
  value: number;
  popInScale: number;
}> = ({ progress, color, size, strokeWidth, label, value, popInScale }) => {
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const strokeDashoffset = circumference - progress * circumference;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        transform: `scale(${popInScale})`,
        opacity: popInScale > 0.1 ? 1 : 0,
        transition: "none",
      }}
    >
      <div style={{ position: "relative", width: size, height: size }}>
        {/* Background Track */}
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ position: "absolute", top: 0, left: 0 }}>
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            stroke={color}
            opacity={0.15}
            strokeWidth={strokeWidth}
          />
        </svg>
        
        {/* Animated Arc */}
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ position: "absolute", top: 0, left: 0 }}>
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            stroke={color}
            strokeWidth={strokeWidth}
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
            style={{
              transform: "rotate(-90deg)",
              transformOrigin: "50% 50%",
              transition: "none",
            }}
          />
        </svg>
      </div>
      
      {/* Values & Labels */}
      <div style={{ marginTop: 24, textAlign: "center" }}>
        <div style={{ 
          fontSize: 64, 
          fontWeight: 800, 
          color: color, 
          letterSpacing: "-0.04em",
          lineHeight: 1 
        }}>
          {Math.round(value * 100)}%
        </div>
        <div style={{ 
          fontSize: 20, 
          fontWeight: 700, 
          color: "rgba(255, 255, 255, 0.4)", 
          marginTop: 16,
          letterSpacing: "0.05em",
          textTransform: "uppercase"
        }}>
          {label}
        </div>
      </div>
    </div>
  );
};

const ImageIcon: React.FC<{ color: string }> = ({ color }) => (
  <svg 
    width="40" 
    height="40" 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke={color} 
    strokeWidth="1.5" 
    strokeLinecap="round" 
    strokeLinejoin="round"
  >
    <rect x="3" y="3" width="18" height="18" rx="4" ry="4"/>
    <circle cx="8.5" cy="8.5" r="1.5"/>
    <polyline points="21 15 16 10 5 21"/>
  </svg>
);

const PieChartsComparison: React.FC<PieChartsComparisonProps> = ({
  backgroundColor = "#04060c",
  transparentBackground = false,
  durationInSeconds = 8,
  
  leftChartColor = "#d4ae60",
  leftChartValue = 0.9,
  leftChartLabel = "Calidad real",
  
  rightChartColor = "#757a82",
  rightChartValue = 0.22,
  rightChartLabel = "Lo que comunica",
  
  footerText = "Invisible para quien no te conoce",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Layout calculations
  const chartSize = Math.min(width * 0.35, 360);
  const strokeWidth = chartSize * 0.12;

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global Camera Push-In
  const globalScale = interpolate(
    frame, 
    [0, fps * durationInSeconds], 
    [1, 1.06], 
    { extrapolateRight: "clamp" }
  );

  // Animations: Left Chart
  const leftPopIn = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  
  const leftProgress = interpolate(
    frame,
    [20, 70],
    [0, leftChartValue],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Animations: Right Chart
  const rightPopIn = spring({
    frame: frame - 18,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const rightProgress = interpolate(
    frame,
    [28, 78],
    [0, rightChartValue],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Animations: Dashed Ghost Card
  const cardOpacity = interpolate(
    frame,
    [50, 80],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const cardY = interpolate(
    frame,
    [50, 80],
    [60, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Background radial glow */}
      {!transparentBackground && (
        <div style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          background: "radial-gradient(circle at center, rgba(32, 50, 80, 0.3) 0%, transparent 60%)",
        }} />
      )}

      {/* Main Container with Camera Push */}
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${globalScale})`,
          transition: "none",
        }}
      >
        {/* Charts Row */}
        <div 
          style={{ 
            display: "flex", 
            flexDirection: "row", 
            gap: width * 0.08,
            alignItems: "flex-start",
            justifyContent: "center",
            width: "100%",
          }}
        >
          <DonutChart
            progress={leftProgress}
            color={leftChartColor}
            size={chartSize}
            strokeWidth={strokeWidth}
            label={leftChartLabel}
            value={leftProgress}
            popInScale={leftPopIn}
          />
          
          <DonutChart
            progress={rightProgress}
            color={rightChartColor}
            size={chartSize}
            strokeWidth={strokeWidth}
            label={rightChartLabel}
            value={rightProgress}
            popInScale={rightPopIn}
          />
        </div>

        {/* Ghost Card Footer */}
        <div
          style={{
            marginTop: 80,
            width: width * 0.8,
            maxWidth: 800,
            padding: "32px 40px",
            borderRadius: 32,
            backgroundColor: "rgba(10, 15, 25, 0.3)",
            border: "2px dashed rgba(255, 255, 255, 0.08)",
            backdropFilter: "blur(12px)",
            WebkitBackdropFilter: "blur(12px)",
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            justifyContent: "flex-start",
            gap: 32,
            opacity: cardOpacity,
            transform: `translateY(${cardY}px)`,
            transition: "none",
            boxShadow: "0 20px 40px rgba(0,0,0,0.4)"
          }}
        >
          {/* Inner Icon Box */}
          <div style={{ 
            width: 80, 
            height: 80, 
            borderRadius: 24, 
            border: "2px solid rgba(255, 255, 255, 0.05)",
            backgroundColor: "rgba(255, 255, 255, 0.02)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0
          }}>
            <ImageIcon color="rgba(255, 255, 255, 0.3)" />
          </div>
          <div style={{
            fontSize: 32,
            fontWeight: 500,
            fontStyle: "italic",
            color: "rgba(255, 255, 255, 0.4)",
            textAlign: "left",
            letterSpacing: "-0.01em",
            lineHeight: 1.2,
          }}>
            {footerText}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PieChartsComparison;